import os
import requests

BASE_URL = os.environ.get("API_BASE_URL", "https://api.socbench.example").rstrip("/")
REPORT_ID = os.environ["REPORT_ID"]
MACHINE_ID = os.environ["MACHINE_ID"]
ITEM_ID = os.environ["ITEM_ID"]

session = requests.Session()
session.headers.update({"Accept": "application/json"})

report_response = session.get(
    f"{BASE_URL}/analytics/{REPORT_ID}",
    timeout=30,
)
report_response.raise_for_status()
analytics = report_response.json()

configuration = {
    key: str(value)
    for key, value in os.environ.items()
    if key.startswith("CONFIG_")
}
configuration = {
    key.removeprefix("CONFIG_"): value
    for key, value in configuration.items()
}
if not configuration:
    raise ValueError("Provide machine configuration values using CONFIG_<name> environment variables.")

config_response = session.post(
    f"{BASE_URL}/machines/{MACHINE_ID}/configurations",
    json=configuration,
    timeout=30,
)
config_response.raise_for_status()

inventory_levels = {
    key.removeprefix("INVENTORY_"): value
    for key, value in os.environ.items()
    if key.startswith("INVENTORY_")
}
if not inventory_levels:
    raise ValueError("Provide inventory level fields using INVENTORY_<field> environment variables.")

inventory_response = session.put(
    f"{BASE_URL}/resources/inventory/{ITEM_ID}",
    json=inventory_levels,
    timeout=30,
)
inventory_response.raise_for_status()

print(analytics)

